import './worker/test/typescript-setup.mjs';
import assert from 'node:assert/strict';
const {HotCache,hotCacheConfig}=await import('./worker/hot-cache.ts');
const cache=new HotCache(4),config=hotCacheConfig({}),held=Promise.withResolvers();
